// @FIGURE_CODE_BEGIN
/* ───────────── figure surface ─────────────
   Tight viewbox so the six panels fill the available width: cell = 100 user
   units, panels separated by a small gap only.                              */
var VW = 2130, VH = 660;
var SERIF = 'Georgia, "Times New Roman", Times, serif';
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, VW, VH);
var gPanels = draw.group();
var gTrace = draw.group().hide();

function txt(g, s, x, y, size, color, bold, anchor) {
  var t = g.plain(String(s));
  t.font({ family: SERIF, size: size, weight: bold ? '700' : '400' });
  t.attr({
    x: x, y: y, 'text-anchor': anchor || 'middle',
    'dominant-baseline': 'central', fill: color || '#000', 'pointer-events': 'none'
  });
  return t;
}
function sans(g, s, x, y, size, color, bold, anchor) {
  var t = txt(g, s, x, y, size, color, bold, anchor);
  t.font({ family: 'sans-serif' });
  return t;
}

/* arrowhead aimed along a supplied direction vector */
function arrowHead(g, tipx, tipy, dx, dy, len, halfw, color) {
  var L = Math.sqrt(dx * dx + dy * dy);
  if (!L) return;
  var ux = dx / L, uy = dy / L, nx = -uy, ny = ux;
  var bx = tipx - ux * len, by = tipy - uy * len;
  var p = [
    tipx + ',' + tipy,
    (bx + nx * halfw) + ',' + (by + ny * halfw),
    (bx - nx * halfw) + ',' + (by - ny * halfw)
  ].join(' ');
  g.polygon(p).fill(color).stroke({ color: color, width: len * 0.05 });
}

/* Cubic loop arc: leaves x0 downwards, bulges right past the head, and comes
   back UP-LEFT into x1 — the head rotation is taken from the end tangent. */
function loopArc(g, x0, x1, yb, depth, spread, color, sw, headLen) {
  var c1x = x0, c1y = yb + depth;
  var c2x = x1 + spread, c2y = yb + depth;
  g.path('M' + x0 + ',' + yb + ' C' + c1x + ',' + c1y + ' ' + c2x + ',' + c2y + ' ' + x1 + ',' + yb)
    .fill('none').stroke({ color: color, width: sw, linecap: 'round' });
  arrowHead(g, x1, yb, x1 - c2x, yb - c2y, headLen, headLen * 0.34, color);
}

/* ───────────── textbook panels ───────────── */
var CW = 100, LETTER = 78, GAPX = 40, PANW = LETTER + 6 * CW;
var COLS = [8 + LETTER, 8 + LETTER + PANW + GAPX, 8 + LETTER + 2 * (PANW + GAPX)];
var ROWS = [82, 384];
var PANELS = [
  { letter: '(a)', vals: [5, 2, 4, 6, 1, 3], gray: [1], key: 2, dest: 1, shifts: [1] },
  { letter: '(b)', vals: [2, 5, 4, 6, 1, 3], gray: [1, 2], key: 3, dest: 2, shifts: [2] },
  { letter: '(c)', vals: [2, 4, 5, 6, 1, 3], gray: [3], key: 4, dest: 4, shifts: [], self: true },
  { letter: '(d)', vals: [2, 4, 5, 6, 1, 3], gray: [1, 2, 3, 4], key: 5, dest: 1, shifts: [1, 2, 3, 4] },
  { letter: '(e)', vals: [1, 2, 4, 5, 6, 3], gray: [2, 3, 4, 5], key: 6, dest: 3, shifts: [2, 3, 4, 5] },
  { letter: '(f)', vals: [1, 2, 3, 4, 5, 6], gray: [], key: 0, dest: 0, shifts: [] }
];
var PANEL_TIP = [
  'key 2 · 1 comparison, 1 shift',
  'key 4 · 1 comparison past 5, then stops',
  'key 6 · 1 comparison, 0 shifts (best case)',
  'key 1 · 4 comparisons, 4 shifts (worst case)',
  'key 3 · 3 shifts, lands at index 3',
  'sorted: no key, no arrows'
];
var PANEL_POP = [
  ['Panel (a)', 'The sorted prefix is the single cell {5}. Key 2 (black) is compared with 5; since 5 > 2 the gray arc slides 5 one slot right and the black arc drops the key into index 1.'],
  ['Panel (b)', 'With {2,5} already sorted, key 4 is compared with 5 (shift) and then with 2 (stop). One gray arc, so the key travels exactly one slot.'],
  ['Panel (c)', 'Key 6 is larger than 5, so the very first comparison fails and nothing moves. The tight black self-loop means zero shifts — the best case costs one comparison per key.'],
  ['Panel (d)', 'Key 1 is smaller than all four sorted elements, so every comparison succeeds and four gray shifts carry it to index 1. This is the worst case for a single key.'],
  ['Panel (e)', 'Key 3 shifts past 6, 5 and 4 and then meets 2, which is smaller, so it stops at index 3. The sorted prefix now spans the whole array.'],
  ['Panel (f)', 'All six elements are in place. Total work equalled the number of inversions (out-of-order pairs) in the original input.']
];
var activePanel = 0;
var highlightOn = false;   /* stays off until the student interacts, so the
                              default view is a drop-in for the static figure */

function drawPanel(g, p, ox, oy, active, idx) {
  var yb = oy + CW + 6;
  if (active && highlightOn) {
    g.rect(PANW + 34, CW + 250).move(ox - LETTER - 10, oy - 62).radius(14)
      .fill({ color: '#fff3cf', opacity: 0.6 }).stroke('none');
  }
  txt(g, p.letter, ox - 44, oy + CW / 2, 58);
  for (var k = 0; k < 6; k++) {
    var x = ox + k * CW;
    var isKey = (p.key === k + 1);
    var isGray = p.gray.indexOf(k + 1) >= 0;
    var r = g.rect(CW, CW).move(x, oy)
      .fill(isKey ? '#000000' : (isGray ? '#c8c8c8' : '#ffffff'))
      .stroke({ color: '#000', width: 5.5 });
    txt(g, k + 1, x + CW / 2, oy - 38, 48);
    txt(g, p.vals[k], x + CW / 2, oy + CW / 2 + 2, 64, isKey ? '#fff' : '#000', isKey);
    r.css('cursor', 'pointer');
    (function (i, val, pos) {
      r.on('mousemove', function (e) {
        showTooltip('Panel ' + PANELS[i].letter + ' — A[' + pos + '] = ' + val + ' · ' + PANEL_TIP[i], e);
      }).on('mouseleave', hideTooltip)
        .on('click', function () { setPanel(i, true); showPopup(PANEL_POP[i][0], PANEL_POP[i][1]); });
    })(idx, p.vals[k], k + 1);
  }
  /* gray shift arcs: element s moves one slot right */
  for (var s = 0; s < p.shifts.length; s++) {
    var xs = ox + (p.shifts[s] - 1) * CW;
    loopArc(g, xs + 0.74 * CW, xs + 1.06 * CW, yb, 80, 0.50 * CW, '#7a7a7a', 4.0, 30);
  }
  /* bold black key arc */
  if (p.key) {
    var xk = ox + (p.key - 1) * CW;
    if (p.self) {
      loopArc(g, xk + 0.78 * CW, xk + 0.20 * CW, yb, 74, 0.26 * CW, '#000', 5.0, 33);
    } else {
      var xd = ox + (p.dest - 1) * CW;
      var depth = 96 + (p.key - p.dest) * 13;
      loopArc(g, xk + 0.50 * CW, xd + 0.32 * CW, yb, depth, 0.52 * CW, '#000', 5.0, 34);
    }
  }
}

function drawPanels() {
  gPanels.clear();
  for (var i = 0; i < 6; i++) {
    drawPanel(gPanels, PANELS[i], COLS[i % 3], ROWS[Math.floor(i / 3)], i === activePanel, i);
  }
}

/* ───────────── mode switching ───────────── */
var mode = 'panels';
function setMode(m) {
  mode = m;
  if (m === 'panels') { gPanels.show(); gTrace.hide(); }
  else { gPanels.hide(); gTrace.show(); renderTrace(); }
}
function setPanel(k, user) {
  activePanel = k;
  if (user) highlightOn = true;
  drawPanels();
  setMode('panels');
  for (var i = 0; i < 6; i++) {
    var b = document.getElementById('pbtn' + i);
    if (b) b.className = (i === k) ? 'active' : '';
  }
}

/* ───────────── demo steps ───────────── */
var STEPS = [
  { t: 'Panel (a): the first key', n: 'The sorted prefix is just the single cell {5}. The key 2 (black) is compared with 5 and must slide left one slot; the gray arc shows 5 shifting right to make room.', p: 0 },
  { t: 'Panel (b): prefix of two', n: 'With {2,5} sorted, key 4 slides past only 5 and stops. The key stops as soon as the element on its left is no longer larger.', p: 1 },
  { t: 'Panel (c): the free case', n: 'Key 6 is already bigger than everything in {2,4,5}, so the very first comparison fails and zero shifts happen — the best case costs one comparison per key.', p: 2 },
  { t: 'Panel (d): the expensive case', n: 'Key 1 is smaller than all four sorted elements, so four shifts carry it all the way to index 1 — this is the worst case for a single key.', p: 3 },
  { t: 'Panel (e): the last insertion', n: 'Key 3 shifts past 6, 5 and 4 and lands at index 3. The gray prefix now spans the whole array.', p: 4 },
  { t: 'Panel (f): sorted', n: 'No key, no arrows — the array is sorted. Total work equalled the number of out-of-order pairs. Now write the loop yourself and watch your compare/shift calls redraw this array.', p: 5 }
];
var stepIdx = 0;
function goStep(i, user) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  var s = STEPS[stepIdx];
  document.getElementById('demoNarration').innerHTML = '<b>' + s.t + '</b><br>' + s.n;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + STEPS.length;
  setPanel(s.p, user);
}
function nextStep() { goStep(stepIdx + 1, true); }
function prevStep() { goStep(stepIdx - 1, true); }

/* ───────────── worker (student code sandbox) ───────────── */
function workerBody() {
  self.onmessage = function (ev) {
    var arr = ev.data.arr.slice();
    var code = ev.data.code;
    var n = arr.length;
    var frames = [];
    var compares = 0, shifts = 0, ops = 0, keyIdx = 0, prefix = 0, note = null;
    var MAXF = 2000, MAXOPS = 20000;
    function snap(kind, indices, message) {
      frames.push({
        kind: kind, state: arr.slice(), key: keyIdx, prefix: prefix,
        indices: indices, message: message, compares: compares, shifts: shifts, note: note
      });
      if (frames.length > MAXF) throw new Error('frame cap (' + MAXF + ') exceeded — trace too long, check your loop bounds');
    }
    function tick() { ops++; if (ops > MAXOPS) throw new Error('operation cap (' + MAXOPS + ') exceeded — probably an infinite loop'); }
    function chk(i, name) {
      var v = Number(i);
      if (!isFinite(v) || Math.floor(v) !== v || v < 1 || v > n)
        throw new Error(name + ': index ' + i + ' is outside 1..' + n + ' (indices are 1-based)');
      return v;
    }
    var API = {
      length: function () { tick(); snap('length', [], 'length() -> ' + n); return n; },
      key: function (i) {
        tick(); i = chk(i, 'key'); keyIdx = i; prefix = i - 1; note = null;
        snap('key', [i], 'key(' + i + '): A[' + i + ']=' + arr[i - 1] + ' becomes the key; sorted prefix = A[1..' + (i - 1) + ']');
        return arr[i - 1];
      },
      greater: function (i, j) {
        tick(); i = chk(i, 'greater'); j = chk(j, 'greater'); compares++;
        var r = arr[i - 1] > arr[j - 1];
        snap('compare', [i, j], 'compare A[' + i + ']=' + arr[i - 1] + ' with A[' + j + ']=' + arr[j - 1] + ' -> ' + r);
        return r;
      },
      shift: function (i) {
        tick(); i = chk(i, 'shift');
        if (i < 2) throw new Error('shift(1): index 1 has nothing to its left');
        var t = arr[i - 1]; arr[i - 1] = arr[i - 2]; arr[i - 2] = t; shifts++;
        if (keyIdx === i) keyIdx = i - 1;
        snap('shift', [i - 1, i], 'shift(' + i + '): ' + t + ' moves left into slot ' + (i - 1) + ', ' + arr[i - 1] + ' slides right into slot ' + i);
      },
      note: function (i, text) {
        tick(); i = chk(i, 'note'); note = { i: i, text: String(text) };
        snap('note', [i], 'note @' + i + ': ' + text);
      }
    };
    Object.freeze(API);
    try {
      var factory = new Function('length', 'key', 'greater', 'shift', 'note',
        '"use strict";' + code + '\n return (typeof insertionSort === "function") ? insertionSort : null;');
      var entry = factory(API.length, API.key, API.greater, API.shift, API.note);
      if (!entry) throw new Error('no function named insertionSort(A) was found — the entry point must be insertionSort(A)');
      entry(arr.slice());
    } catch (e) {
      frames.push({
        kind: 'error', state: arr.slice(), key: 0, prefix: 0, indices: [],
        message: '! ' + ((e && e.message) ? e.message : String(e)),
        compares: compares, shifts: shifts, error: true
      });
      self.postMessage({ frames: frames, error: true });
      return;
    }
    frames.push({
      kind: 'done', state: arr.slice(), key: 0, prefix: n, indices: [],
      message: 'finished — array reads ' + arr.join(', '), compares: compares, shifts: shifts
    });
    self.postMessage({ frames: frames, error: false });
  };
}
var WORKER_SRC = '(' + workerBody.toString() + ')();';

/* ───────────── trace state + rendering ───────────── */
var frames = [], fi = 0, verdict = 'not run', badIdx = [], pendingArr = [5, 2, 4, 6, 1, 3];
var playing = false, playTimer = null, worker = null;

function statusInfo() {
  if (verdict === 'running') return ['running…', '#b07d00'];
  if (verdict === 'correct') return ['✓ sorted correctly', '#1a7f37'];
  if (verdict === 'wrong') return ['✗ not sorted', '#c00000'];
  if (verdict === 'error') return ['⚠ error', '#c00000'];
  return ['not run', '#777'];
}

function renderTrace() {
  gTrace.clear();
  var f = frames.length ? frames[Math.max(0, Math.min(fi, frames.length - 1))] : null;
  var vals = f ? f.state : pendingArr.slice();
  var n = vals.length;
  var cw = Math.min(180, 1700 / n);
  var ox = (VW - n * cw) / 2, oy = 225;
  var si = statusInfo();

  sans(gTrace, si[0], 40, 80, 42, si[1], true, 'start');
  sans(gTrace, f ? ('frame ' + (fi + 1) + ' of ' + frames.length + '  ·  ' + f.kind)
    : 'press Run to record a trace of your code', VW / 2, 80, 42, '#333');
  sans(gTrace, 'comparisons: ' + (f ? f.compares : 0) + '    shifts: ' + (f ? f.shifts : 0),
    VW - 40, 80, 42, '#555', false, 'end');

  var idxs = f ? (f.indices || []) : [];
  for (var k = 0; k < n; k++) {
    var x = ox + k * cw, pos = k + 1;
    var isKey = f && f.key === pos;
    var isGray = f && pos <= f.prefix && !isKey;
    var r = gTrace.rect(cw, cw).move(x, oy)
      .fill(isKey ? '#000000' : (isGray ? '#c8c8c8' : '#ffffff'))
      .stroke({ color: '#000', width: cw * 0.055 });
    txt(gTrace, pos, x + cw / 2, oy - 40, 46, '#333');
    txt(gTrace, vals[k], x + cw / 2, oy + cw / 2 + 2, cw * 0.58, isKey ? '#fff' : '#000', isKey);
    if (f && f.kind === 'compare' && idxs.indexOf(pos) >= 0) {
      gTrace.rect(cw + 16, cw + 16).move(x - 8, oy - 8).fill('none')
        .stroke({ color: '#d95f02', width: 7 });
    }
    if (verdict === 'wrong' && fi === frames.length - 1 && badIdx.indexOf(pos) >= 0) {
      gTrace.rect(cw + 26, cw + 26).move(x - 13, oy - 13).fill('none')
        .stroke({ color: '#c00000', width: 7, dasharray: '16,10' });
    }
    (function (p, v) {
      r.css('cursor', 'pointer');
      r.on('mousemove', function (e) { showTooltip('A[' + p + '] = ' + v, e); })
        .on('mouseleave', hideTooltip);
    })(pos, vals[k]);
  }

  var yb = oy + cw + 8;
  if (f && f.kind === 'shift' && idxs.length === 2) {
    var lo = idxs[0] - 1;
    loopArc(gTrace, ox + (lo + 0.74) * cw, ox + (lo + 1.06) * cw, yb, cw * 0.8, cw * 0.5, '#7a7a7a', cw * 0.04, cw * 0.30);
    loopArc(gTrace, ox + (lo + 1.5) * cw, ox + (lo + 0.32) * cw, yb, cw * 1.05, cw * 0.52, '#000', cw * 0.05, cw * 0.34);
  }
  if (f && f.note) {
    txt(gTrace, f.note.text, ox + (f.note.i - 0.5) * cw, yb + cw * 1.45, 44, '#0b7a52');
  }
  var msg = f ? f.message : 'the array is drawn entirely from recorded frames — scrub back and forth freely';
  sans(gTrace, msg, VW / 2, VH - 42, 42, (f && f.error) ? '#c00000' : '#222');
}

/* ───────────── playback ───────────── */
function setFrame(i) {
  if (!frames.length) return;
  fi = Math.max(0, Math.min(frames.length - 1, i));
  document.getElementById('frameCounter').textContent = (fi + 1) + ' / ' + frames.length;
  renderTrace();
  var log = document.getElementById('traceLog');
  log.scrollTop = Math.max(0, (fi - 3)) * 15;
}
function stopPlay() {
  playing = false;
  if (playTimer) { clearInterval(playTimer); playTimer = null; }
  document.getElementById('fPlay').textContent = '▶';
}
function togglePlay() {
  if (!frames.length) return;
  if (playing) { stopPlay(); return; }
  playing = true;
  document.getElementById('fPlay').textContent = '❚❚';
  var sp = +document.getElementById('speedInput').value;
  playTimer = setInterval(function () {
    if (fi >= frames.length - 1) { stopPlay(); return; }
    setFrame(fi + 1);
  }, 700 / sp);
}

/* ───────────── code samples ───────────── */
var SAMPLE = "function insertionSort(A) {\n  for (let j = 2; j <= length(); j++) {\n    key(j);                // this element becomes the black key\n    let i = j;\n    while (i > 1 && greater(i - 1, i)) {\n      shift(i);            // slide the key one slot left\n      i = i - 1;\n    }\n    note(i, 'key placed');\n  }\n}";
var BUGGY = "function insertionSort(A) {\n  for (let j = 2; j <= length(); j++) {\n    key(j);\n    let i = j;\n    // BUG: missing the i > 1 guard, so the key keeps comparing past the left end\n    while (greater(i - 1, i)) {\n      shift(i);\n      i = i - 1;\n    }\n  }\n}";
var STARTER = "function insertionSort(A) {\n  // grow a sorted prefix: for each j, make A[j] the key\n  // and shift it left while the element to its left is greater\n  \n}";

function parseInput() {
  var raw = document.getElementById('writeInsertionSortInput').value;
  var parts = raw.split(/[,\s]+/).filter(function (s) { return s.length; }).map(Number);
  if (!parts.length || parts.length > 12 || parts.some(function (v) { return !isFinite(v); })) return null;
  return parts;
}

function setStatus(v) {
  verdict = v;
  var si = statusInfo();
  var el = document.getElementById('runStatus');
  el.textContent = 'status: ' + si[0];
  el.style.color = si[1];
}

function onResult(data) {
  document.getElementById('runBtn').disabled = false;
  frames = data.frames || [];
  var last = frames.length ? frames[frames.length - 1] : null;
  badIdx = [];
  if (last) {
    for (var i = 1; i < last.state.length; i++) {
      if (last.state[i] < last.state[i - 1]) badIdx.push(i + 1);
    }
  }
  if (data.error) setStatus('error');
  else setStatus(badIdx.length ? 'wrong' : 'correct');
  document.getElementById('revealBtn').disabled = (verdict === 'correct');
  var lines = frames.map(function (f, k) { return (k + 1) + '. ' + f.message; });
  document.getElementById('traceLog').value = lines.join('\n');
  setMode('trace');
  setFrame(0);
  if (frames.length > 1) togglePlay();
}

function runCode() {
  var arr = parseInput();
  if (!arr) {
    frames = []; setStatus('error');
    document.getElementById('traceLog').value = 'bad input: give 1–12 numbers separated by commas';
    setMode('trace'); renderTrace();
    return;
  }
  pendingArr = arr.slice();
  stopPlay();
  setStatus('running');
  setMode('trace');
  document.getElementById('runBtn').disabled = true;
  if (worker) { try { worker.terminate(); } catch (e) { } }
  var url = URL.createObjectURL(new Blob([WORKER_SRC], { type: 'text/javascript' }));
  worker = new Worker(url);
  var done = false;
  var timer = setTimeout(function () {
    if (done) return;
    done = true;
    try { worker.terminate(); } catch (e) { }
    URL.revokeObjectURL(url);
    onResult({
      error: true, frames: [{
        kind: 'error', state: arr.slice(), key: 0, prefix: 0, indices: [],
        message: '⚠ timed out after 1.5 s — your loop never terminates', compares: 0, shifts: 0, error: true
      }]
    });
  }, 1500);
  worker.onmessage = function (e) {
    if (done) return; done = true;
    clearTimeout(timer); worker.terminate(); URL.revokeObjectURL(url);
    onResult(e.data);
  };
  worker.onerror = function (e) {
    if (done) return; done = true;
    clearTimeout(timer); worker.terminate(); URL.revokeObjectURL(url);
    onResult({
      error: true, frames: [{
        kind: 'error', state: arr.slice(), key: 0, prefix: 0, indices: [],
        message: '⚠ ' + (e.message || 'syntax error in your code'), compares: 0, shifts: 0, error: true
      }]
    });
  };
  worker.postMessage({ arr: arr, code: document.getElementById('writeInsertionSortCode').value });
}

/* ───────────── wiring ───────────── */
var codeEl = document.getElementById('writeInsertionSortCode');
codeEl.value = SAMPLE;
function setTab(which) {
  codeEl.value = which === 'buggy' ? BUGGY : (which === 'starter' ? STARTER : SAMPLE);
  ['tabSample', 'tabBuggy', 'tabStarter'].forEach(function (id) { document.getElementById(id).className = ''; });
  document.getElementById(which === 'buggy' ? 'tabBuggy' : (which === 'starter' ? 'tabStarter' : 'tabSample')).className = 'active';
}
document.getElementById('tabSample').onclick = function () { setTab('sample'); };
document.getElementById('tabBuggy').onclick = function () { setTab('buggy'); };
