  showPopup('Reference solution', 'The reference loop makes A[j] the key, then repeatedly swaps it with its left neighbour while i > 1 and that neighbour is greater. The i > 1 guard is what stops the key from running off the front of the array.');
};
document.getElementById('fFirst').onclick = function () { stopPlay(); setFrame(0); };
document.getElementById('fPrev').onclick = function () { stopPlay(); setFrame(fi - 1); };
